def reformatPhoneNumber(number):
    # Remove non-digit characters
    digits = []
    for ch in number:
        if ch.isdigit():
            digits.append(ch)
    n = len(digits)
    res = []
    i = 0
    while n - i > 4:
        res.append(''.join(digits[i:i+3]))
        i += 3
    # Handle the tail
    if n - i == 4:
        res.append(''.join(digits[i:i+2]))
        res.append(''.join(digits[i+2:i+4]))
    else:
        res.append(''.join(digits[i:]))
    return '-'.join(res)
